-- =============================================================================
-- Enterprise Approval System (EAS) — Full Local Supabase Seed (Schema + Data)
-- =============================================================================
-- Generated for automatic local onboarding (`supabase start` / `supabase db reset`).
-- Includes all 10 application schemas (`eas`, `eas_archive`, 8 `mock_*` schemas),
-- 92 tables, 7,346+ rows, functions, views, triggers, RLS policies, and roles.
-- Safe and idempotent to re-run as `postgres` or `supabase_admin`.

CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS "btree_gist" WITH SCHEMA extensions;

DO $$
DECLARE
  r text;
BEGIN
  FOREACH r IN ARRAY ARRAY[
    'anon',
    'authenticated',
    'service_role',
    'eas_migration',
    'eas_api',
    'eas_worker',
    'eas_privacy',
    'eas_backup',
    'eas_mock'
  ]
  LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
      EXECUTE format('CREATE ROLE %I NOLOGIN', r);
    END IF;
  END LOOP;

  EXECUTE format('GRANT eas_migration TO %I', current_user);
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'postgres') THEN
    EXECUTE 'GRANT eas_migration TO postgres';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'eas_backend_login') THEN
    CREATE ROLE eas_backend_login LOGIN PASSWORD 'postgres' IN ROLE eas_api;
  ELSE
    ALTER ROLE eas_backend_login WITH LOGIN PASSWORD 'postgres';
    GRANT eas_api TO eas_backend_login;
  END IF;
  ALTER ROLE eas_backend_login SET search_path TO pg_catalog, eas;
  ALTER ROLE eas_backend_login SET statement_timeout TO '30s';
  ALTER ROLE eas_backend_login SET lock_timeout TO '5s';

  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'eas_worker_login') THEN
    CREATE ROLE eas_worker_login LOGIN PASSWORD 'postgres' IN ROLE eas_worker;
  ELSE
    ALTER ROLE eas_worker_login WITH LOGIN PASSWORD 'postgres';
    GRANT eas_worker TO eas_worker_login;
  END IF;
  ALTER ROLE eas_worker_login SET search_path TO pg_catalog, eas;
  ALTER ROLE eas_worker_login SET statement_timeout TO '30s';
  ALTER ROLE eas_worker_login SET lock_timeout TO '5s';

  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'eas_mock_login') THEN
    CREATE ROLE eas_mock_login LOGIN PASSWORD 'postgres' IN ROLE eas_mock;
  ELSE
    ALTER ROLE eas_mock_login WITH LOGIN PASSWORD 'postgres';
    GRANT eas_mock TO eas_mock_login;
  END IF;
END
$$;

DROP SCHEMA IF EXISTS
  eas,
  eas_archive,
  mock_assets,
  mock_crm,
  mock_facilities,
  mock_finance,
  mock_hr,
  mock_it,
  mock_procurement,
  mock_travel
CASCADE;

