--
-- Name: advance_audit_head(); Type: FUNCTION; Schema: eas; Owner: eas_migration
--

CREATE FUNCTION eas.advance_audit_head() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'eas'
    AS $$
DECLARE scope text; h eas.audit_head;
BEGIN
 IF TG_TABLE_NAME='audit_event' THEN scope:='REQ:'||NEW.request_id::text; ELSE scope:='ADMIN'; END IF;
 SELECT * INTO h FROM eas.audit_head WHERE scope_key=scope FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23503',MESSAGE='Audit head not found'; END IF;
 IF NEW.seq<>h.seq+1 OR NEW.prev_hash<>h.last_hash THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Audit sequence/previous hash mismatch'; END IF;
 UPDATE eas.audit_head SET seq=NEW.seq,last_hash=NEW.hash WHERE scope_key=scope;
 RETURN NEW;
END $$;


ALTER FUNCTION eas.advance_audit_head() OWNER TO eas_migration;

--
-- Name: ai_revocable(uuid); Type: FUNCTION; Schema: eas; Owner: eas_migration
--

CREATE FUNCTION eas.ai_revocable(p_request uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'eas'
    AS $$
  SELECT COALESCE((
    SELECT d.actor_id = '00000002-0000-4000-8000-0000000000a1'::uuid
       AND d.decided_at > statement_timestamp() - interval '24 hours'
    FROM eas.approval_decision d
    JOIN eas.approval_step s ON s.id = d.step_id
    JOIN eas.workflow_instance i ON i.id = s.instance_id
    JOIN eas.request r ON r.id = d.request_id AND r.current_revision_id = i.revision_id
    WHERE d.request_id = p_request
    ORDER BY d.decided_at DESC
    LIMIT 1
  ), false)
$$;


ALTER FUNCTION eas.ai_revocable(p_request uuid) OWNER TO eas_migration;

--
-- Name: assert_privacy_delete(uuid); Type: FUNCTION; Schema: eas; Owner: eas_migration
--

CREATE FUNCTION eas.assert_privacy_delete(p_request uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'eas'
    AS $$
DECLARE c uuid; owner_user uuid;
BEGIN
 IF current_user<>'eas_privacy' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='History deletion requires eas_privacy role'; END IF;
 c:=nullif(current_setting('eas.privacy_case_id',true),'')::uuid;
 IF c IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Approved privacy case required'; END IF;
 PERFORM eas.lock_security(true);
 SELECT requester_id INTO owner_user FROM eas.request WHERE id=p_request FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23503',MESSAGE='Privacy scope request missing'; END IF;
 IF NOT EXISTS (SELECT 1 FROM eas.privacy_case WHERE id=c AND subject_user_id=owner_user AND case_type='ERASE' AND status='APPROVED' AND decision_reference IS NOT NULL) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Privacy case not approved for this request owner';
 END IF;
 IF EXISTS(SELECT 1 FROM eas.retention_hold WHERE request_id=p_request AND released_at IS NULL) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Open legal hold blocks deletion';
 END IF;
END $$;


ALTER FUNCTION eas.assert_privacy_delete(p_request uuid) OWNER TO eas_migration;

--
-- Name: check_hierarchy(); Type: FUNCTION; Schema: eas; Owner: eas_migration
--

CREATE FUNCTION eas.check_hierarchy() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'eas'
    AS $$
DECLARE bad boolean;
BEGIN
 IF TG_TABLE_NAME='department' THEN
  WITH RECURSIVE p AS (
   SELECT id,parent_id,ARRAY[id] AS path,false AS cycle FROM eas.department WHERE id=NEW.id
   UNION ALL SELECT d.id,d.parent_id,p.path||d.id,d.id=ANY(p.path)
    FROM eas.department d JOIN p ON d.id=p.parent_id WHERE NOT p.cycle
  ) SELECT coalesce(bool_or(cycle),false) INTO bad FROM p;
 ELSE
  WITH RECURSIVE p AS (
   SELECT id,manager_id,ARRAY[id] AS path,false AS cycle FROM eas.app_user WHERE id=NEW.id
   UNION ALL SELECT d.id,d.manager_id,p.path||d.id,d.id=ANY(p.path)
    FROM eas.app_user d JOIN p ON d.id=p.manager_id WHERE NOT p.cycle
  ) SELECT coalesce(bool_or(cycle),false) INTO bad FROM p;
 END IF;
 IF bad THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='EAS hierarchy cycle'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION eas.check_hierarchy() OWNER TO eas_migration;

--
-- Name: check_submission_files(); Type: FUNCTION; Schema: eas; Owner: eas_migration
--

CREATE FUNCTION eas.check_submission_files() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'eas'
    AS $$
DECLARE a eas.execution_attempt; n integer; tcode varchar(30);
BEGIN
 IF TG_TABLE_NAME='execution_attempt' THEN
  SELECT * INTO a FROM eas.execution_attempt WHERE id=NEW.id;
  IF NOT FOUND OR a.submitted_at IS NULL THEN RETURN NULL; END IF;
  SELECT count(*) INTO n FROM eas.execution_attachment WHERE attempt_id=a.id;
  IF n NOT BETWEEN 1 AND 5 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Submitted result requires 1..5 evidence files'; END IF;
 ELSE
  SELECT rt.code INTO tcode FROM eas.request_revision v JOIN eas.config_release c ON c.id=v.release_id JOIN eas.request_type rt ON rt.id=c.type_id WHERE v.id=NEW.id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT count(*) INTO n FROM eas.revision_attachment WHERE revision_id=NEW.id;
  IF n>5 OR (tcode='EQUIPMENT' AND n=0) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Equipment revision requires quote; maximum five files'; END IF;
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION eas.check_submission_files() OWNER TO eas_migration;

--
-- Name: complete_ai_regulation_learning(); Type: FUNCTION; Schema: eas; Owner: eas_migration
--

CREATE FUNCTION eas.complete_ai_regulation_learning() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE eas.ai_system_state
    SET active_regulation_version = target_regulation_version,
        sync_status = 'COMPLETED',
        current_step_index = 4,
        current_step_label = 'Đã học xong và áp dụng quy định mới (v' || target_regulation_version || ')',
        progress_percent = 100,
        client_maintenance_lock = false,
        steps_detail = '[
            {"step": 1, "code": "SYNCING", "label": "Tiếp nhận quy định mới từ Admin", "status": "DONE"},
            {"step": 2, "code": "LEARNING", "label": "AI phân tích ngữ nghĩa & Huấn luyện lại Vector", "status": "DONE"},
            {"step": 3, "code": "APPLYING", "label": "Áp dụng bộ quy tắc mới vào luồng phê duyệt", "status": "DONE"},
            {"step": 4, "code": "COMPLETED", "label": "Hoàn tất & Mở khóa Web Client", "status": "DONE"}
        ]'::jsonb,
        updated_at = now()
    WHERE id = 1;
END;
$$;


ALTER FUNCTION eas.complete_ai_regulation_learning() OWNER TO eas_migration;

--
-- Name: enforce_account_role_type(); Type: FUNCTION; Schema: eas; Owner: eas_migration
--

CREATE FUNCTION eas.enforce_account_role_type() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'eas'
    AS $$
DECLARE kind text;
BEGIN
  IF NEW.revoked_at IS NOT NULL OR (NEW.valid_to IS NOT NULL AND NEW.valid_to <= statement_timestamp()) THEN
    RETURN NEW;
  END IF;
  SELECT account_type INTO kind FROM eas.app_user WHERE id = NEW.user_id;
  IF kind = 'ADMIN' AND NEW.role IN ('REQUESTER', 'APPROVER', 'EXECUTOR', 'ACCEPTOR') THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'ADMIN_ACCOUNT_CANNOT_HOLD_OPERATIONAL_ROLE';
  END IF;
  IF kind = 'EMPLOYEE' AND NEW.role IN ('OPS_ADMIN', 'POLICY_ADMIN') THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'EMPLOYEE_ACCOUNT_CANNOT_HOLD_ADMIN_ROLE';
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION eas.enforce_account_role_type() OWNER TO eas_migration;

--
-- Name: fn_after_regulation_versioning(); Type: FUNCTION; Schema: eas; Owner: eas_migration
--

CREATE FUNCTION eas.fn_after_regulation_versioning() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'eas'
    AS $$
DECLARE
  v_action text; v_summary text; v_major int; v_minor int; v_ver text; v_reg uuid; v_title text; v_content text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_action := 'CREATE'; v_reg := NEW.id; v_title := NEW.title; v_content := NEW.content;
    v_major := NEW.major_version; v_minor := NEW.minor_version; v_ver := NEW.version_string;
    v_summary := 'Thêm mới quy định "' || NEW.title || '"';
  ELSIF TG_OP = 'UPDATE' THEN
    IF COALESCE(OLD.is_deleted, false) = false AND COALESCE(NEW.is_deleted, false) = true THEN
      v_action := 'DELETE_MAJOR';
      v_summary := 'Gỡ bỏ quy định "' || NEW.title || '"';
    ELSIF NEW.version_string IS DISTINCT FROM OLD.version_string THEN
      v_action := 'UPDATE_MINOR';
      v_summary := 'Cập nhật quy định "' || NEW.title || '"';
    ELSE
      RETURN NEW;
    END IF;
    v_reg := NEW.id; v_title := NEW.title; v_content := NEW.content;
    v_major := NEW.major_version; v_minor := NEW.minor_version; v_ver := NEW.version_string;
  ELSE
    SELECT COALESCE(global_major_version, 1) + 1, 0 INTO v_major, v_minor FROM eas.ai_system_state WHERE id = 1;
    v_ver := v_major || '.' || v_minor;
    v_action := 'DELETE_MAJOR'; v_reg := NULL; v_title := OLD.title; v_content := OLD.content;
    v_summary := 'Gỡ bỏ quy định "' || OLD.title || '"';
  END IF;

  INSERT INTO eas.regulation_versions (regulation_id, version_string, major_version, minor_version,
                                       action_type, title, content, change_summary, created_by)
  VALUES (v_reg, v_ver, v_major, v_minor, v_action, v_title, v_content, v_summary,
          COALESCE(CASE WHEN TG_OP = 'DELETE' THEN OLD.updated_by ELSE NEW.updated_by END, 'Admin'));

  -- Chỉ cấp số phiên bản mới; việc học/khoá/thông báo do eas.ai_learning_job đảm nhận.
  UPDATE eas.ai_system_state
  SET global_major_version = v_major, global_minor_version = v_minor,
      target_regulation_version = v_ver, updated_at = now()
  WHERE id = 1;
  RETURN COALESCE(NEW, OLD);
END
$$;


ALTER FUNCTION eas.fn_after_regulation_versioning() OWNER TO eas_migration;

--
-- Name: fn_before_regulation_versioning(); Type: FUNCTION; Schema: eas; Owner: eas_migration
--

CREATE FUNCTION eas.fn_before_regulation_versioning() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_cur_major INT;
    v_cur_minor INT;
BEGIN
    SELECT COALESCE(global_major_version, 1), COALESCE(global_minor_version, 0)
    INTO v_cur_major, v_cur_minor
    FROM eas.ai_system_state
    WHERE id = 1;

    IF TG_OP = 'INSERT' THEN
        -- Thêm mới 1 quy định -> Tăng phiên bản LỚN (Major Version)
        v_cur_major := v_cur_major + 1;
        v_cur_minor := 0;
        NEW.major_version := v_cur_major;
        NEW.minor_version := v_cur_minor;
        NEW.version_string := v_cur_major || '.' || v_cur_minor;
        NEW.updated_at := now();
        RETURN NEW;

    ELSIF TG_OP = 'UPDATE' THEN
        -- Nếu xóa mềm quy định (is_deleted chuyển từ false sang true) -> Tăng phiên bản LỚN (Major)
        IF COALESCE(OLD.is_deleted, false) = false AND COALESCE(NEW.is_deleted, false) = true THEN
            v_cur_major := v_cur_major + 1;
            v_cur_minor := 0;
            NEW.major_version := v_cur_major;
            NEW.minor_version := v_cur_minor;
            NEW.version_string := v_cur_major || '.' || v_cur_minor;
            NEW.updated_at := now();
        -- Nếu sửa nội dung hoặc tiêu đề của 1 quy định -> Tăng phiên bản NHỎ (Minor)
        ELSIF NEW.content IS DISTINCT FROM OLD.content OR NEW.title IS DISTINCT FROM OLD.title OR NEW.category IS DISTINCT FROM OLD.category THEN
            v_cur_minor := v_cur_minor + 1;
            NEW.major_version := v_cur_major;
            NEW.minor_version := v_cur_minor;
            NEW.version_string := v_cur_major || '.' || v_cur_minor;
            NEW.updated_at := now();
        END IF;
        RETURN NEW;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION eas.fn_before_regulation_versioning() OWNER TO eas_migration;

--
-- Name: get_effective_user_permissions(uuid); Type: FUNCTION; Schema: eas; Owner: eas_migration
--

CREATE FUNCTION eas.get_effective_user_permissions(p_user_id uuid) RETURNS TABLE(module_code text, module_name text, group_name text, route_path text, icon_name text, target_app text, can_view boolean, can_create boolean, can_update boolean, can_delete boolean, show_on_sidebar boolean, permission_source text)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'eas'
    AS $$
      WITH rp AS (
        SELECT p.module_code,
               bool_or(p.can_view) AS v, bool_or(p.can_create) AS c,
               bool_or(p.can_update) AS u, bool_or(p.can_delete) AS d
        FROM eas.role_membership m
        JOIN eas.role_module_permission p ON p.role_code = m.role
        WHERE m.user_id = p_user_id AND m.revoked_at IS NULL
          AND m.valid_from <= statement_timestamp()
          AND (m.valid_to IS NULL OR m.valid_to > statement_timestamp())
        GROUP BY p.module_code
      )
      SELECT m.code, m.name, m.group_name, m.route_path, m.icon_name, m.target_app,
             COALESCE(up.can_view, rp.v, false),
             COALESCE(up.can_create, rp.c, false),
             COALESCE(up.can_update, rp.u, false),
             COALESCE(up.can_delete, rp.d, false),
             COALESCE(up.can_view, rp.v, false) OR COALESCE(up.can_create, rp.c, false)
               OR COALESCE(up.can_update, rp.u, false) OR COALESCE(up.can_delete, rp.d, false),
             CASE WHEN up.id IS NOT NULL THEN 'USER_OVERRIDE' ELSE 'ROLE_DEFAULT' END
      FROM eas.modules m
      LEFT JOIN rp ON rp.module_code = m.code
      LEFT JOIN eas.user_permissions up ON up.user_id = p_user_id AND up.module_code = m.code
      ORDER BY m.sort_order, m.code
    $$;


ALTER FUNCTION eas.get_effective_user_permissions(p_user_id uuid) OWNER TO eas_migration;

--
-- Name: get_user_requests_detail(uuid); Type: FUNCTION; Schema: eas; Owner: eas_migration
--

CREATE FUNCTION eas.get_user_requests_detail(p_user_id uuid) RETURNS TABLE(request_id uuid, request_code text, title text, content text, request_type text, category_code text, current_stage text, current_stage_label text, final_status text, user_role_in_request text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'eas'
    AS $$
    SELECT
        r.id AS request_id,
        r.code AS request_code,
        COALESCE(r.draft_payload->>'title', 'Yêu cầu ' || r.code) AS title,
        r.draft_payload->>'content' AS content,
        COALESCE(rt.code, 'GENERAL') AS request_type,
        COALESCE(rt.category, 'B') AS category_code,
        CASE r.status
            WHEN 'DRAFT' THEN 'YEU_CAU'
            WHEN 'PENDING' THEN 'PHE_DUYET'
            WHEN 'IN_PROGRESS' THEN 'THUC_HIEN'
            WHEN 'APPROVED' THEN 'HOAN_THANH'
            WHEN 'COMPLETED' THEN 'HOAN_THANH'
            ELSE 'YEU_CAU'
        END AS current_stage,
        CASE r.status
            WHEN 'DRAFT' THEN '1. Yêu cầu'
            WHEN 'PENDING' THEN '2. Phê duyệt'
            WHEN 'IN_PROGRESS' THEN '3. Thực hiện'
            WHEN 'APPROVED' THEN '5. Hoàn thành'
            WHEN 'COMPLETED' THEN '5. Hoàn thành'
            ELSE '1. Yêu cầu'
        END AS current_stage_label,
        CASE r.status
            WHEN 'APPROVED' THEN 'APPROVED'
            WHEN 'COMPLETED' THEN 'APPROVED'
            WHEN 'REJECTED' THEN 'REJECTED'
            ELSE 'PROCESSING'
        END AS final_status,
        CASE WHEN r.requester_id = p_user_id THEN 'Người yêu cầu' ELSE 'Người liên quan' END AS user_role_in_request,
        r.created_at
    FROM eas.request r
    LEFT JOIN eas.request_type rt ON rt.id = r.type_id
    WHERE r.requester_id = p_user_id
    ORDER BY r.created_at DESC;
$$;


ALTER FUNCTION eas.get_user_requests_detail(p_user_id uuid) OWNER TO eas_migration;

--
-- Name: get_user_working_status(uuid, timestamp with time zone); Type: FUNCTION; Schema: eas; Owner: eas_migration
--

CREATE FUNCTION eas.get_user_working_status(p_user_id uuid, p_check_time timestamp with time zone DEFAULT now()) RETURNS TABLE(status_code text, status_label text, detail_reason text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'eas'
    AS $$
DECLARE
  v_leave record;
  v_local timestamp := p_check_time AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_dow int := extract(isodow FROM v_local);
  v_time time := v_local::time;
BEGIN
  SELECT l.type, l.title INTO v_leave
  FROM eas.user_leave_and_trips l
  WHERE l.user_id = p_user_id
    AND l.approval_status = 'APPROVED'
    AND p_check_time >= l.start_time AND p_check_time < l.end_time
  ORDER BY (l.type = 'BUSINESS_TRIP'), l.created_at DESC
  LIMIT 1;

  IF FOUND THEN
    IF v_leave.type = 'BUSINESS_TRIP' THEN
      RETURN QUERY SELECT 'CONG_TAC'::text, 'Công tác'::text, v_leave.title::text;
    ELSE
      RETURN QUERY SELECT 'NGHI_LAM'::text, 'Nghỉ làm'::text, v_leave.title::text;
    END IF;
    RETURN;
  END IF;

  IF v_dow BETWEEN 1 AND 5 THEN
    IF (v_time >= time '08:00' AND v_time < time '12:00')
       OR (v_time >= time '13:30' AND v_time < time '17:30') THEN
      RETURN QUERY SELECT 'DANG_LAM'::text, 'Đang làm'::text,
        'Giờ làm việc (08:00–12:00, 13:30–17:30, T2–T6)'::text;
      RETURN;
    END IF;
    IF v_time >= time '12:00' AND v_time < time '13:30' THEN
      RETURN QUERY SELECT 'NGOAI_GIO'::text, 'Nghỉ trưa'::text, 'Nghỉ trưa (12:00–13:30)'::text;
      RETURN;
    END IF;
  END IF;
  RETURN QUERY SELECT 'NGOAI_GIO'::text, 'Ngoài giờ làm việc'::text,
    'Ngoài giờ làm việc (08:00–12:00, 13:30–17:30, T2–T6)'::text;
END
$$;


ALTER FUNCTION eas.get_user_working_status(p_user_id uuid, p_check_time timestamp with time zone) OWNER TO eas_migration;

--
-- Name: guard_account_type_change(); Type: FUNCTION; Schema: eas; Owner: eas_migration
--

CREATE FUNCTION eas.guard_account_type_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'eas'
    AS $$
BEGIN
  IF NEW.account_type IS DISTINCT FROM OLD.account_type AND EXISTS (
    SELECT 1 FROM eas.role_membership m
    WHERE m.user_id = NEW.id AND m.revoked_at IS NULL
      AND (m.valid_to IS NULL OR m.valid_to > statement_timestamp())
      AND m.role = ANY (CASE WHEN NEW.account_type = 'ADMIN'
                             THEN ARRAY['REQUESTER', 'APPROVER', 'EXECUTOR', 'ACCEPTOR']
                             ELSE ARRAY['OPS_ADMIN', 'POLICY_ADMIN'] END)
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'ACCOUNT_TYPE_CONFLICTS_WITH_ACTIVE_ROLES';
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION eas.guard_account_type_change() OWNER TO eas_migration;

--
-- Name: guard_active_release(); Type: FUNCTION; Schema: eas; Owner: eas_migration
--

CREATE FUNCTION eas.guard_active_release() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.id<>OLD.id OR NEW.code<>OLD.code) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Request type identity immutable';
 END IF;
 IF NEW.active_release_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eas.config_release WHERE id=NEW.active_release_id AND type_id=NEW.id AND state='PUBLISHED') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Active release must be published for this type';
 END IF;
 RETURN NEW;
END;
$$;


ALTER FUNCTION eas.guard_active_release() OWNER TO eas_migration;

--
-- Name: guard_append_only(); Type: FUNCTION; Schema: eas; Owner: eas_migration
--

CREATE FUNCTION eas.guard_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'eas'
    AS $$
DECLARE req uuid;
BEGIN
 IF TG_OP='DELETE' AND current_user='eas_privacy' AND TG_TABLE_NAME<>'admin_event' THEN
  req:=nullif(to_jsonb(OLD)->>'request_id','')::uuid;
  IF req IS NOT NULL THEN PERFORM eas.assert_privacy_delete(req); RETURN OLD; END IF;
 END IF;
 RAISE EXCEPTION USING ERRCODE='23514',MESSAGE=TG_TABLE_NAME||' is append-only';
END $$;


ALTER FUNCTION eas.guard_append_only() OWNER TO eas_migration;

--
-- Name: guard_attachment(); Type: FUNCTION; Schema: eas; Owner: eas_migration
--

CREATE FUNCTION eas.guard_attachment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'eas'
    AS $$
DECLARE used_bytes bigint;
BEGIN
 PERFORM eas.lock_security(false);
 PERFORM 1 FROM eas.request WHERE id=NEW.request_id FOR UPDATE;
 IF TG_OP='INSERT' THEN
  SELECT coalesce(sum(size_bytes),0) INTO used_bytes FROM eas.attachment WHERE request_id=NEW.request_id AND deleted_at IS NULL;
  IF NEW.deleted_at IS NULL AND used_bytes+NEW.size_bytes>209715200 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Attachment quota 200 MiB exceeded'; END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['scan_state','scan_attempts','scanned_at','deleted_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['scan_state','scan_attempts','scanned_at','deleted_at']) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Attachment object metadata immutable';
  END IF;
  IF OLD.deleted_at IS NOT NULL AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Deleted attachment cannot be restored by update'; END IF;
 END IF;
 IF NEW.deleted_at IS NOT NULL AND (TG_OP='INSERT' OR OLD.deleted_at IS NULL) THEN
  IF EXISTS(SELECT 1 FROM eas.retention_hold WHERE request_id=NEW.request_id AND released_at IS NULL)
   OR EXISTS(SELECT 1 FROM eas.draft_attachment WHERE attachment_id=NEW.id)
   OR EXISTS(SELECT 1 FROM eas.revision_attachment WHERE attachment_id=NEW.id)
   OR EXISTS(SELECT 1 FROM eas.execution_attachment WHERE attachment_id=NEW.id) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Referenced or held attachment cannot be deleted';
  END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION eas.guard_attachment() OWNER TO eas_migration;

--
-- Name: guard_attempt(); Type: FUNCTION; Schema: eas; Owner: eas_migration
--

CREATE FUNCTION eas.guard_attempt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'eas'
    AS $$
DECLARE lc char(1);
BEGIN
 SELECT lifecycle INTO lc FROM eas.workflow_instance WHERE id=NEW.instance_id;
 IF FOUND AND (lc='A' OR (lc='B' AND (NEW.state='SUBMITTED' OR NEW.closure_kind IN ('ACCEPTED','REWORK'))) OR (lc='C' AND NEW.closure_kind='SUCCESS')) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Attempt lifecycle mismatch';
 END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.id,NEW.request_id,NEW.instance_id,NEW.attempt_no) IS DISTINCT FROM ROW(OLD.id,OLD.request_id,OLD.instance_id,OLD.attempt_no) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Attempt identity immutable';
  END IF;
  IF OLD.state='FINISHED' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Finished attempt immutable'; END IF;
  IF OLD.state IN ('RUNNING','SUBMITTED') AND NEW.executor_id<>OLD.executor_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Reassignment requires a new attempt'; END IF;
  IF OLD.state='SUBMITTED' AND (to_jsonb(NEW)-ARRAY['state','closure_kind','closed_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','closure_kind','closed_at']) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Submitted result immutable';
  END IF;
  IF NEW.state<>OLD.state AND NOT ((OLD.state='READY' AND NEW.state='RUNNING') OR (OLD.state='RUNNING' AND NEW.state IN ('SUBMITTED','FINISHED')) OR (OLD.state='SUBMITTED' AND NEW.state='FINISHED')) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Attempt transition invalid';
  END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION eas.guard_attempt() OWNER TO eas_migration;

