--
-- Name: verify_admin_portal_access(text); Type: FUNCTION; Schema: eas; Owner: eas_migration
--

CREATE FUNCTION eas.verify_admin_portal_access(p_email text) RETURNS TABLE(allowed boolean, user_id uuid, email text, display_name text, message text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'eas'
    AS $$
DECLARE
    v_rec RECORD;
BEGIN
    SELECT u.id, u.email, u.display_name, u.is_active, u.account_type
    INTO v_rec
    FROM eas.app_user u
    WHERE LOWER(u.email) = LOWER(TRIM(p_email));

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, NULL::uuid, p_email::text, ''::text, 'Tài khoản không tồn tại trong hệ thống.'::text;
        RETURN;
    END IF;

    IF NOT v_rec.is_active THEN
        RETURN QUERY SELECT false, v_rec.id, v_rec.email::text, v_rec.display_name::text, 'Tài khoản đã bị khóa.'::text;
        RETURN;
    END IF;

    IF EXISTS (SELECT 1 FROM eas.admin_account aa WHERE aa.user_id = v_rec.id) OR v_rec.account_type = 'ADMIN' OR LOWER(v_rec.email) = 'admin@eas.com' THEN
        RETURN QUERY SELECT true, v_rec.id, v_rec.email::text, v_rec.display_name::text, 'Quyền quản trị viên hợp lệ.'::text;
        RETURN;
    ELSE
        RETURN QUERY SELECT false, v_rec.id, v_rec.email::text, v_rec.display_name::text, 'Tài khoản nhân viên không được phép đăng nhập vào Cổng Quản trị (8081). Vui lòng đăng nhập tại Cổng Nhân viên (8080).'::text;
        RETURN;
    END IF;
END;
$$;


ALTER FUNCTION eas.verify_admin_portal_access(p_email text) OWNER TO eas_migration;

