--
-- Name: fn_log_template_changes(); Type: FUNCTION; Schema: eas_archive; Owner: eas_migration
--

CREATE FUNCTION eas_archive.fn_log_template_changes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.category_code IS DISTINCT FROM OLD.category_code THEN
        INSERT INTO eas.system_versions_changelog (
            system_version, change_type, change_scope, title, description, old_value, new_value
        ) VALUES (
            'v' || (SELECT active_regulation_version FROM eas.ai_system_state WHERE id = 1),
            'WORKFLOW', 'MINOR',
            'Chuyển phân loại mẫu "' || NEW.name || '" từ nhóm ' || OLD.category_code || ' sang nhóm ' || NEW.category_code,
            'Quy trình xử lý của mẫu yêu cầu đã tự động cập nhật theo chuẩn phân loại ' || NEW.category_code,
            jsonb_build_object('category_code', OLD.category_code, 'workflow_steps', OLD.workflow_steps),
            jsonb_build_object('category_code', NEW.category_code, 'workflow_steps', NEW.workflow_steps)
        );
    ELSIF NEW.automation_weight IS DISTINCT FROM OLD.automation_weight THEN
        INSERT INTO eas.system_versions_changelog (
            system_version, change_type, change_scope, title, description, old_value, new_value
        ) VALUES (
            'v' || (SELECT active_regulation_version FROM eas.ai_system_state WHERE id = 1),
            'TEMPLATE', 'PATCH',
            'Điều chỉnh trọng số tự động mẫu "' || NEW.name || '" (' || OLD.automation_weight || '% -> ' || NEW.automation_weight || '%)',
            'Cập nhật trọng số tính tự động cho mẫu yêu cầu.',
            jsonb_build_object('automation_weight', OLD.automation_weight),
            jsonb_build_object('automation_weight', NEW.automation_weight)
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION eas_archive.fn_log_template_changes() OWNER TO eas_migration;

--
-- Name: fn_propagate_category_workflow(); Type: FUNCTION; Schema: eas_archive; Owner: eas_migration
--

CREATE FUNCTION eas_archive.fn_propagate_category_workflow() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.workflow_steps IS DISTINCT FROM OLD.workflow_steps THEN
        UPDATE eas.request_templates
        SET workflow_steps = NEW.workflow_steps,
            updated_at = now()
        WHERE category_code = NEW.category_code;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION eas_archive.fn_propagate_category_workflow() OWNER TO eas_migration;

--
-- Name: fn_sync_template_workflow_by_category(); Type: FUNCTION; Schema: eas_archive; Owner: eas_migration
--

CREATE FUNCTION eas_archive.fn_sync_template_workflow_by_category() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_cat_steps JSONB;
BEGIN
    IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND NEW.category_code IS DISTINCT FROM OLD.category_code) THEN
        SELECT workflow_steps INTO v_cat_steps
        FROM eas.workflow_categories
        WHERE category_code = NEW.category_code;

        IF v_cat_steps IS NOT NULL AND (TG_OP = 'UPDATE' OR NEW.workflow_steps IS NULL OR NEW.workflow_steps = '[]'::jsonb) THEN
            NEW.workflow_steps := v_cat_steps;
        END IF;
    END IF;
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;


ALTER FUNCTION eas_archive.fn_sync_template_workflow_by_category() OWNER TO eas_migration;

--
-- Name: get_user_requests_detail(uuid); Type: FUNCTION; Schema: eas_archive; Owner: eas_migration
--

CREATE FUNCTION eas_archive.get_user_requests_detail(p_user_id uuid) RETURNS TABLE(request_id uuid, request_code text, title text, content text, request_type text, category_code text, current_stage text, current_stage_label text, final_status text, user_role_in_request text, created_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
    SELECT
        r.id AS request_id,
        r.request_code,
        r.title,
        r.content,
        r.request_type,
        r.category_code,
        r.current_stage,
        CASE r.current_stage
            WHEN 'YEU_CAU' THEN '1. Yêu cầu'
            WHEN 'PHE_DUYET' THEN '2. Phê duyệt'
            WHEN 'THUC_HIEN' THEN '3. Thực hiện'
            WHEN 'NGHIEM_THU' THEN '4. Nghiệm thu'
            WHEN 'HOAN_THANH' THEN '5. Hoàn thành'
        END AS current_stage_label,
        r.final_status,
        ARRAY_TO_STRING(ARRAY_REMOVE(ARRAY[
            CASE WHEN r.requester_id = p_user_id THEN 'Người yêu cầu' END,
            CASE WHEN r.approver_id = p_user_id THEN 'Người phê duyệt' END,
            CASE WHEN r.executor_id = p_user_id THEN 'Người thực hiện' END,
            CASE WHEN r.evaluator_id = p_user_id THEN 'Người nghiệm thu' END,
            CASE WHEN r.completer_id = p_user_id THEN 'Người hoàn thành' END
        ], NULL), ', ') AS user_role_in_request,
        r.created_at
    FROM eas.requests r
    WHERE p_user_id IN (r.requester_id, r.approver_id, r.executor_id, r.evaluator_id, r.completer_id)
    ORDER BY r.created_at DESC;
$$;


ALTER FUNCTION eas_archive.get_user_requests_detail(p_user_id uuid) OWNER TO eas_migration;

--
-- Name: guard_loan_overlap(); Type: FUNCTION; Schema: mock_assets; Owner: eas_migration
--

CREATE FUNCTION mock_assets.guard_loan_overlap() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'mock_assets'
    AS $$
BEGIN
  IF NEW.status IN ('RESERVED','ACTIVE','OVERDUE') THEN
    PERFORM 1 FROM mock_assets.asset WHERE id=NEW.asset_id FOR UPDATE;
    IF EXISTS (
      SELECT 1 FROM mock_assets.asset_loan l
      WHERE l.asset_id=NEW.asset_id AND l.id<>NEW.id
        AND l.status IN ('RESERVED','ACTIVE','OVERDUE')
        AND tstzrange(l.starts_at,l.due_at,'[)') && tstzrange(NEW.starts_at,NEW.due_at,'[)')
    ) THEN
      RAISE EXCEPTION USING ERRCODE='23P01',MESSAGE='asset loan overlaps existing allocation';
    END IF;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION mock_assets.guard_loan_overlap() OWNER TO eas_migration;

--
-- Name: guard_reservation_overlap(); Type: FUNCTION; Schema: mock_facilities; Owner: eas_migration
--

CREATE FUNCTION mock_facilities.guard_reservation_overlap() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'mock_facilities'
    AS $$
BEGIN
  IF NEW.status IN ('TENTATIVE','CONFIRMED','CHECKED_IN') THEN
    PERFORM 1 FROM mock_facilities.resource WHERE id=NEW.resource_id FOR UPDATE;
    IF EXISTS (
      SELECT 1 FROM mock_facilities.reservation r
      WHERE r.resource_id=NEW.resource_id AND r.id<>NEW.id
        AND r.status IN ('TENTATIVE','CONFIRMED','CHECKED_IN')
        AND tstzrange(r.starts_at,r.ends_at,'[)') && tstzrange(NEW.starts_at,NEW.ends_at,'[)')
    ) THEN
      RAISE EXCEPTION USING ERRCODE='23P01',MESSAGE='facility reservation overlaps existing allocation';
    END IF;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION mock_facilities.guard_reservation_overlap() OWNER TO eas_migration;

