--
-- Name: acceptance_decision; Type: TABLE; Schema: eas; Owner: eas_migration
--

CREATE TABLE eas.acceptance_decision (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    outcome character varying(6) NOT NULL,
    reason character varying(2000),
    decided_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT acceptance_decision_outcome_check CHECK (((outcome)::text = ANY (ARRAY[('ACCEPT'::character varying)::text, ('REWORK'::character varying)::text]))),
    CONSTRAINT acceptance_reason CHECK ((((outcome)::text = 'ACCEPT'::text) OR ((reason IS NOT NULL) AND ((length(btrim((reason)::text)) >= 10) AND (length(btrim((reason)::text)) <= 2000)))))
);


ALTER TABLE eas.acceptance_decision OWNER TO eas_migration;

--
