    CONSTRAINT approval_step_step_no_check CHECK (((step_no >= 1) AND (step_no <= 5))),
    CONSTRAINT approval_step_tier_level_check CHECK (((tier_level >= 1) AND (tier_level <= 5))),
    CONSTRAINT step_state_times CHECK (((((state)::text = 'WAITING'::text) AND (activated_at IS NULL) AND (closed_at IS NULL)) OR (((state)::text = 'ACTIVE'::text) AND (activated_at IS NOT NULL) AND (closed_at IS NULL)) OR (((state)::text = ANY (ARRAY[('APPROVED'::character varying)::text, ('REJECTED'::character varying)::text, ('NEEDS_INFO'::character varying)::text])) AND (activated_at IS NOT NULL) AND (closed_at IS NOT NULL)) OR (((state)::text = 'SKIPPED'::text) AND (closed_at IS NOT NULL)))),
    CONSTRAINT step_time_order CHECK (((closed_at IS NULL) OR (activated_at IS NULL) OR (closed_at >= activated_at)))
);


