    CONSTRAINT attachment_scan_attempts_check CHECK (((scan_attempts >= 0) AND (scan_attempts <= 3))),
    CONSTRAINT attachment_scan_state_check CHECK (((scan_state)::text = ANY (ARRAY[('QUEUED'::character varying)::text, ('CLEAN'::character varying)::text, ('INFECTED'::character varying)::text, ('ERROR'::character varying)::text]))),
    CONSTRAINT attachment_scan_time CHECK ((((scan_state)::text = 'QUEUED'::text) OR ((scanned_at IS NOT NULL) AND (scan_attempts >= 1)))),
    CONSTRAINT attachment_sha256_check CHECK ((sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT attachment_size_bytes_check CHECK (((size_bytes >= 1) AND (size_bytes <= 10485760))),
    CONSTRAINT attachment_storage_key_check CHECK ((length((storage_key)::text) > 0)),
    CONSTRAINT attachment_times CHECK ((((scanned_at IS NULL) OR (scanned_at >= created_at)) AND ((deleted_at IS NULL) OR (deleted_at >= created_at))))
);


