--
-- Name: execution_attempt; Type: TABLE; Schema: eas; Owner: eas_migration
--

CREATE TABLE eas.execution_attempt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_id uuid NOT NULL,
    instance_id uuid NOT NULL,
    attempt_no integer NOT NULL,
    executor_id uuid NOT NULL,
    state character varying(9) DEFAULT 'READY'::character varying NOT NULL,
    closure_kind character varying(10),
    result_note character varying(4000),
    external_reference character varying(200),
    started_at timestamp with time zone,
    submitted_at timestamp with time zone,
    closed_at timestamp with time zone,
    CONSTRAINT attempt_closure CHECK (((((state)::text = 'FINISHED'::text) AND (closure_kind IS NOT NULL) AND (closed_at IS NOT NULL)) OR (((state)::text <> 'FINISHED'::text) AND (closure_kind IS NULL) AND (closed_at IS NULL)))),
    CONSTRAINT attempt_finished_result CHECK ((((state)::text <> 'FINISHED'::text) OR (((closure_kind)::text = 'REASSIGNED'::text) AND (submitted_at IS NULL)) OR (((closure_kind)::text = ANY (ARRAY[('SUCCESS'::character varying)::text, ('ACCEPTED'::character varying)::text, ('REWORK'::character varying)::text])) AND (submitted_at IS NOT NULL)))),
    CONSTRAINT attempt_progress CHECK (((((state)::text = 'READY'::text) AND (started_at IS NULL) AND (submitted_at IS NULL)) OR (((state)::text = 'RUNNING'::text) AND (started_at IS NOT NULL) AND (submitted_at IS NULL)) OR (((state)::text = 'SUBMITTED'::text) AND (started_at IS NOT NULL) AND (submitted_at IS NOT NULL)) OR (((state)::text = 'FINISHED'::text) AND (started_at IS NOT NULL)))),
    CONSTRAINT attempt_result CHECK ((((submitted_at IS NULL) AND (result_note IS NULL) AND (external_reference IS NULL)) OR ((submitted_at IS NOT NULL) AND (result_note IS NOT NULL) AND ((length(btrim((result_note)::text)) >= 10) AND (length(btrim((result_note)::text)) <= 4000)) AND (external_reference IS NOT NULL) AND ((length(btrim((external_reference)::text)) >= 1) AND (length(btrim((external_reference)::text)) <= 200))))),
    CONSTRAINT attempt_time_order CHECK ((((submitted_at IS NULL) OR (submitted_at >= started_at)) AND ((closed_at IS NULL) OR (closed_at >= started_at)) AND ((closed_at IS NULL) OR (submitted_at IS NULL) OR (closed_at >= submitted_at)))),
    CONSTRAINT execution_attempt_attempt_no_check CHECK ((attempt_no > 0)),
    CONSTRAINT execution_attempt_closure_kind_check CHECK (((closure_kind)::text = ANY (ARRAY[('SUCCESS'::character varying)::text, ('ACCEPTED'::character varying)::text, ('REWORK'::character varying)::text, ('REASSIGNED'::character varying)::text]))),
    CONSTRAINT execution_attempt_state_check CHECK (((state)::text = ANY (ARRAY[('READY'::character varying)::text, ('RUNNING'::character varying)::text, ('SUBMITTED'::character varying)::text, ('FINISHED'::character varying)::text])))
);


