    CONSTRAINT outbox_lease CHECK (((((state)::text = 'PROCESSING'::text) AND (lease_token IS NOT NULL) AND (lease_until IS NOT NULL) AND (attempts >= 1)) OR (((state)::text <> 'PROCESSING'::text) AND (lease_token IS NULL) AND (lease_until IS NULL)))),
    CONSTRAINT outbox_sent CHECK ((((state)::text = 'SENT'::text) = (sent_at IS NOT NULL))),
