--
-- Name: v_request_templates_full; Type: VIEW; Schema: eas_archive; Owner: eas_migration
--

CREATE VIEW eas_archive.v_request_templates_full AS
 SELECT rt.id,
    rt.code,
    rt.name,
    rt.request_type,
    rt.category_code,
    wc.name AS category_name,
    wc.sla_hours,
    rt.automation_weight,
    rt.form_schema,
    rt.workflow_steps,
    rt.linked_api_id,
    ma.api_code,
    ma.api_name,
    ma.source_system AS api_source_system,
    COALESCE(ma.is_enabled, true) AS is_api_enabled,
    (rt.is_active AND COALESCE(ma.is_enabled, true)) AS can_use_template,
        CASE
            WHEN ((ma.id IS NOT NULL) AND (ma.is_enabled = false)) THEN (((('Yêu cầu này hiện không thể sử dụng do kết nối API của hệ thống "'::text || ma.source_system) || '" ('::text) || ma.api_name) || ') đang bị tắt.'::text)
            WHEN (rt.is_active = false) THEN 'Mẫu yêu cầu này đang tạm ngưng hoạt động.'::text
            ELSE NULL::text
        END AS unavailable_notice,
    rt.is_active,
    rt.updated_at
   FROM ((eas_archive.request_templates rt
     LEFT JOIN eas_archive.workflow_categories wc ON ((wc.category_code = rt.category_code)))
     LEFT JOIN eas.mock_apis ma ON ((ma.id = rt.linked_api_id)));


ALTER VIEW eas_archive.v_request_templates_full OWNER TO eas_migration;

--
-- Name: v_users_management; Type: VIEW; Schema: eas_archive; Owner: eas_migration
--

CREATE VIEW eas_archive.v_users_management AS
 SELECT u.id,
    u.employee_code,
    u.full_name,
    u.email,
    u.job_title,
    u.role_id,
    r.code AS role_code,
    r.name AS role_name,
    u.department_id,
    d.name AS department_name,
    u.avatar_url,
    u.is_active,
    ws.status_code AS working_status_code,
    ws.status_label AS working_status_label,
    ws.detail_reason AS working_status_detail,
    COALESCE(req_stats.yeu_cau_count, (0)::bigint) AS stage_yeu_cau_count,
    COALESCE(req_stats.phe_duyet_count, (0)::bigint) AS stage_phe_duyet_count,
    COALESCE(req_stats.thuc_hien_count, (0)::bigint) AS stage_thuc_hien_count,
    COALESCE(req_stats.nghiem_thu_count, (0)::bigint) AS stage_nghiem_thu_count,
    COALESCE(req_stats.hoan_thanh_count, (0)::bigint) AS stage_hoan_thanh_count,
    COALESCE(req_stats.total_requests, (0)::bigint) AS total_involved_requests
   FROM ((((eas_archive.users u
     LEFT JOIN eas_archive.roles r ON ((r.id = u.role_id)))
     LEFT JOIN eas_archive.departments d ON ((d.id = u.department_id)))
     LEFT JOIN LATERAL eas.get_user_working_status(u.id, now()) ws(status_code, status_label, detail_reason) ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) FILTER (WHERE (req.current_stage = 'YEU_CAU'::text)) AS yeu_cau_count,
            count(*) FILTER (WHERE (req.current_stage = 'PHE_DUYET'::text)) AS phe_duyet_count,
            count(*) FILTER (WHERE (req.current_stage = 'THUC_HIEN'::text)) AS thuc_hien_count,
            count(*) FILTER (WHERE (req.current_stage = 'NGHIEM_THU'::text)) AS nghiem_thu_count,
            count(*) FILTER (WHERE (req.current_stage = 'HOAN_THANH'::text)) AS hoan_thanh_count,
            count(*) AS total_requests
           FROM eas_archive.requests req
          WHERE ((u.id = req.requester_id) OR (u.id = req.approver_id) OR (u.id = req.executor_id) OR (u.id = req.evaluator_id) OR (u.id = req.completer_id))) req_stats ON (true));


ALTER VIEW eas_archive.v_users_management OWNER TO eas_migration;

