INSERT INTO eas.ai_system_state VALUES
	(1, 'Google Gemini + Scikit-Learn Hybrid', 'gemini-2.5-flash & nlp_risk_pipeline_v2', '1.0', '1.0', 1, 0, 'COMPLETED', 4, 'Đã áp dụng quy định v1.0', 100, false, 'Hệ thống AI đang cập nhật quy định mới. Vui lòng đăng nhập lại sau ít phút.', '[{"code": "SYNCING", "step": 1, "label": "Tiếp nhận & chụp bộ quy định hiện hành", "status": "DONE", "percent": 25}, {"code": "LEARNING", "step": 2, "label": "AI phân tích văn bản và trích bộ luật duyệt", "status": "DONE", "percent": 50}, {"code": "APPLYING", "step": 3, "label": "Áp dụng bộ luật vào AI và kiểm thử", "status": "DONE", "percent": 75}, {"code": "COMPLETED", "step": 4, "label": "Hoàn tất, gửi thông báo và mở khoá", "status": "DONE", "percent": 100}]', '2026-11-16 08:57:15.760677+00', '{"rules": [{"id": "REG-002-3", "min_risk": 5, "amount_gt": 49999999, "description": "Phân loại C áp dụng cho ngân sách từ 50.000.000 VNĐ trở lên và bắt buộc qua Ban Giám Đốc phê duyệt.", "auto_approve": false, "request_type": null}], "version": "v1.0"}', '[{"code": "REG-001", "title": "Quy định thời gian làm việc, nghỉ phép và công tác", "content": "Thời gian làm việc tiêu chuẩn của công ty là từ 08:00 sáng đến 17:30 chiều, từ Thứ 2 đến Thứ 6 (nghỉ Thứ 7, Chủ nhật). Nhân viên không có đơn xin nghỉ phép, đi muộn/về sớm hoặc đăng ký công tác đã phê duyệt thì mặc định ở trạng thái Đang làm việc.", "version": "1.0"}, {"code": "REG-002", "title": "Quy định phân loại và hạn mức phê duyệt yêu cầu A, B, C", "content": "Các yêu cầu thuộc Phân loại A được AI đối chiếu tự động theo trọng số. Phân loại B yêu cầu Trưởng bộ phận phê duyệt trong 24h. Phân loại C áp dụng cho ngân sách từ 50.000.000 VNĐ trở lên và bắt buộc qua Ban Giám Đốc phê duyệt.", "version": "1.0"}, {"code": "REG-003", "title": "Quy định bảo mật API và đồng bộ tri thức AI", "content": "Khi cập nhật quy định mới (bản nhỏ hoặc bản lớn), hệ thống tự động đẩy sang AI Service để huấn luyện lại và tạm khóa đăng nhập trên Web Client cho tới khi hoàn tất 100%.", "version": "1.0"}]', '2026-11-16 08:57:15.760677+00', 'fb3bb8ca-32b9-4e67-8126-6482d2cff8e0');


