INSERT INTO eas.company_regulations VALUES
	('5d08535a-ee42-4513-aa32-fc59b5ca02c6', 'REG-001', 'Quy định thời gian làm việc, nghỉ phép và công tác', 'Nhân sự & Chấm công', 'Thời gian làm việc tiêu chuẩn của công ty là từ 08:00 sáng đến 17:30 chiều, từ Thứ 2 đến Thứ 6 (nghỉ Thứ 7, Chủ nhật). Nhân viên không có đơn xin nghỉ phép, đi muộn/về sớm hoặc đăng ký công tác đã phê duyệt thì mặc định ở trạng thái Đang làm việc.', '1.0', 1, 0, false, 'System Admin', '2026-11-02 19:48:37.049747+00', '2026-11-02 19:48:37.049747+00'),
	('5d08535a-ee42-4513-aa32-fc59b5ca02c8', 'REG-003', 'Quy định bảo mật API và đồng bộ tri thức AI', 'Công nghệ & AI', 'Khi cập nhật quy định mới (bản nhỏ hoặc bản lớn), hệ thống tự động đẩy sang AI Service để huấn luyện lại và tạm khóa đăng nhập trên Web Client cho tới khi hoàn tất 100%.', '1.0', 1, 0, false, 'System Admin', '2026-11-02 19:48:37.049747+00', '2026-11-02 19:48:37.049747+00'),
	('5d08535a-ee42-4513-aa32-fc59b5ca02c7', 'REG-002', 'Quy định phân loại và hạn mức phê duyệt yêu cầu A, B, C', 'Quy trình & Tài chính', 'Các yêu cầu thuộc Phân loại A được AI đối chiếu tự động theo trọng số. Phân loại B yêu cầu Trưởng bộ phận phê duyệt trong 24h. Phân loại C áp dụng cho ngân sách từ 50.000.000 VNĐ trở lên và bắt buộc qua Ban Giám Đốc phê duyệt.', '1.0', 1, 0, false, 'System Admin', '2026-11-02 19:48:37.049747+00', '2026-11-02 19:48:37.049747+00');


