INSERT INTO eas.system_announcement VALUES
	('d99c3996-cb81-401f-9be5-8971601a98f0', '88637523-95eb-4221-a981-618e2477c04e', 'REGULATION_UPDATE', 'ALL', '1.0', 'Hệ thống đã cập nhật quy định v1.0', 'Hệ thống đã áp dụng bộ quy định v1.0: 3 quy định mới, 0 quy định cập nhật, 0 quy định bãi bỏ. Có 1 thay đổi về quy trình duyệt — xem hướng dẫn bên dưới.', '[{"kind": "REGULATION_ADDED", "title": "Ban hành REG-001: Quy định thời gian làm việc, nghỉ phép và công tác"}, {"kind": "REGULATION_ADDED", "title": "Ban hành REG-002: Quy định phân loại và hạn mức phê duyệt yêu cầu A, B, C"}, {"kind": "REGULATION_ADDED", "title": "Ban hành REG-003: Quy định bảo mật API và đồng bộ tri thức AI"}, {"kind": "RULE_ADDED", "title": "Mọi yêu cầu có giá trị từ 50.000.000 đ trở lên: bắt buộc người duyệt xét thủ công (mức rủi ro tối thiểu 5/5)."}]', '[{"steps": ["Tạo yêu cầu như bình thường tại “Tạo yêu cầu mới”.", "Yêu cầu thuộc trường hợp này sẽ không được tự động duyệt; hệ thống chuyển tới người phê duyệt theo quy trình.", "Đính kèm đầy đủ chứng từ, giải trình ngay khi tạo để rút ngắn thời gian duyệt.", "Theo dõi tiến độ và phản hồi yêu cầu bổ sung tại “Yêu cầu của tôi”."], "title": "Mọi yêu cầu có giá trị từ 50.000.000 đ trở lên: bắt buộc người duyệt xét thủ công (mức rủi ro tối thiểu 5/5)."}]', '2026-11-03 03:15:25.543327+00'),
	('66f93c79-619a-49f5-84fa-6453362854dc', 'aaf2d1cc-29da-4283-a23a-72f59123db33', 'REGULATION_UPDATE', 'ALL', '1.0', 'Hệ thống đã cập nhật quy định v1.0', 'Hệ thống đã áp dụng bộ quy định v1.0: 0 quy định mới, 0 quy định cập nhật, 0 quy định bãi bỏ. Quy trình thao tác của bạn không thay đổi.', '[]', '[]', '2026-11-03 04:37:58.437326+00'),
	('4b358369-e64e-47bd-ba0a-aa844a1508a4', '614bc446-d239-4ad0-a13e-a68f98dfd125', 'REGULATION_UPDATE_FAILED', 'ADMIN', '1.0', 'AI chưa áp dụng được quy định v1.0', 'Sau 3 lần thử, AI chưa học được bộ quy định mới; hệ thống giữ bộ luật đang hiệu lực và đã mở khoá đăng nhập. Lỗi: ProgrammingError: permission denied for table ai_policy_version. Kiểm tra AI service rồi bấm “Học lại” trong Quản trị AI.', '[]', '[]', '2026-11-10 17:11:48.822452+00'),
	('3da0232a-7ff6-485a-bba7-94641302c62c', '5cd9ac81-3f84-46a3-89f6-d4b51755cb0b', 'REGULATION_UPDATE_FAILED', 'ADMIN', '1.0', 'AI chưa áp dụng được quy định v1.0', 'Sau 3 lần thử, AI chưa học được bộ quy định mới; hệ thống giữ bộ luật đang hiệu lực và đã mở khoá đăng nhập. Lỗi: AI service unreachable: ConnectError. Kiểm tra AI service rồi bấm “Học lại” trong Quản trị AI.', '[]', '[]', '2026-11-15 12:14:23.764457+00');


