INSERT INTO eas_archive.workflow_categories VALUES
	('A', 'Phân loại A - Tự động hóa / Rủi ro thấp', 'Áp dụng cho yêu cầu thông thường, AI kiểm tra quy định và phê duyệt nhanh trong 4 giờ', 4, '[{"name": "Khởi tạo yêu cầu & Kiểm tra API", "step": 1, "actor": "Người yêu cầu", "stage": "YEU_CAU"}, {"name": "AI tự động đối chiếu Quy định & Trọng số", "step": 2, "actor": "AI Engine", "stage": "PHE_DUYET"}, {"name": "Tự động xác nhận & Đóng yêu cầu", "step": 3, "actor": "Hệ thống", "stage": "HOAN_THANH"}]', '2026-11-02 19:48:37.049747+00'),
	('B', 'Phân loại B - Phê duyệt cấp Phòng ban / Trung bình', 'Cần Trưởng bộ phận phê duyệt và bộ phận chuyên môn thực hiện, nghiệm thu trong 24 giờ', 24, '[{"name": "Gửi yêu cầu & AI chấm điểm rủi ro", "step": 1, "actor": "Người yêu cầu", "stage": "YEU_CAU"}, {"name": "Trưởng phòng trực tiếp phê duyệt", "step": 2, "actor": "Trưởng phòng", "stage": "PHE_DUYET"}, {"name": "Bộ phận chuyên trách triển khai", "step": 3, "actor": "Chuyên viên thực hiện", "stage": "THUC_HIEN"}, {"name": "Người yêu cầu kiểm tra & Nghiệm thu", "step": 4, "actor": "Người yêu cầu", "stage": "NGHIEM_THU"}, {"name": "Lưu hồ sơ & Hoàn thành", "step": 5, "actor": "Hệ thống", "stage": "HOAN_THANH"}]', '2026-11-02 19:48:37.049747+00'),
	('C', 'Phân loại C - Phê duyệt Đa cấp & Ban Giám Đốc / Trọng yếu', 'Yêu cầu ngân sách lớn hoặc vượt ngưỡng rủi ro, cần Kế toán thẩm định và Ban Giám Đốc duyệt trong 48 giờ', 48, '[{"name": "Lập tờ trình chi tiết & AI phân tích rủi ro", "step": 1, "actor": "Người yêu cầu", "stage": "YEU_CAU"}, {"name": "Trưởng phòng & Tài chính thẩm định + Ban Giám Đốc phê duyệt", "step": 2, "actor": "Ban Giám Đốc", "stage": "PHE_DUYET"}, {"name": "Thực hiện giải ngân / Mua sắm / Triển khai", "step": 3, "actor": "Phòng Vận hành / Kế toán", "stage": "THUC_HIEN"}, {"name": "Hội đồng nghiệm thu bàn giao chứng từ", "step": 4, "actor": "Ban Nghiệm thu", "stage": "NGHIEM_THU"}, {"name": "Quyết toán & Đóng yêu cầu", "step": 5, "actor": "Hệ thống", "stage": "HOAN_THANH"}]', '2026-11-02 19:48:37.049747+00');


