INSERT INTO eas_archive.workflow_categories_eas VALUES
	('A', 'Phê duyệt Tự động / Chuẩn hóa (Category A)', 'Quy trình nội bộ rủi ro thấp, phê duyệt tự động bằng AI Rule Engine hoặc 1 cấp quản lý trực tiếp.', 4, '[{"name": "Khởi tạo yêu cầu", "step": 1}, {"name": "AI Thẩm định & Tự động phê duyệt", "step": 2}, {"name": "Hoàn tất", "step": 3}]', '2026-11-03 03:12:01.400761+00'),
	('B', 'Phê duyệt Phân cấp Đa tầng (Category B)', 'Quy trình liên phòng ban trung bình, yêu cầu quản lý phòng ban và bộ phận chuyên môn phê duyệt.', 24, '[{"name": "Khởi tạo yêu cầu", "step": 1}, {"name": "Quản lý trực tiếp duyệt", "step": 2}, {"name": "Bộ phận chuyên môn xác nhận", "step": 3}, {"name": "Hoàn tất", "step": 4}]', '2026-11-03 03:12:01.400761+00'),
	('C', 'Phê duyệt Trọng yếu Ban Giám Đốc (Category C)', 'Quy trình ngân sách lớn hoặc tác động chiến lược, yêu cầu Ban Giám Đốc phê duyệt cuối cùng.', 72, '[{"name": "Khởi tạo yêu cầu", "step": 1}, {"name": "Trưởng phòng thẩm định", "step": 2}, {"name": "Ban Giám Đốc phê duyệt", "step": 3}, {"name": "Nghiệm thu & Giải ngân", "step": 4}]', '2026-11-03 03:12:01.400761+00');


