-- Restore explicit owner ACLs on archive schema & ensure private Storage bucket exists
SET ROLE eas_migration;
GRANT ALL ON SCHEMA eas_archive TO eas_migration;
GRANT ALL ON ALL TABLES IN SCHEMA eas_archive TO eas_migration;
RESET ROLE;

DO $$
BEGIN
  IF to_regclass('storage.buckets') IS NOT NULL THEN
    INSERT INTO storage.buckets (id, name, public)
    VALUES ('eas-private', 'eas-private', true)
    ON CONFLICT (id) DO NOTHING;
  END IF;
END
$$;
